package eu.simplexsmp.adminsuite;

import java.io.IOException;
import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.Player;

/** Click-first probe management, shared by Java inventories and native Bedrock forms. */
final class ClientProbeMenus {
    private final SimplexAdminSuite plugin;
    private final ClientProbeManager manager;
    private static final String ROOT=ClientProbeRules.ROOT;
    ClientProbeMenus(SimplexAdminSuite p,ClientProbeManager manager){plugin=p;this.manager=manager;}
    private boolean allowed(Player p){return plugin.has(p,"simplexadminsuite.clientsecurity.admin")&&plugin.adminSessionUsable(p);}
    private String t(Player p,String de,String en){return de;}
    private String state(Player p,boolean value){return value?t(p,"✓ An","✓ On"):t(p,"○ Aus","○ Off");}
    static Material icon(String id){if(id.startsWith("custom-"))return Material.TRIPWIRE_HOOK;if(id.contains("xray"))return Material.DIAMOND_ORE;if(id.contains("freecam"))return Material.SPYGLASS;if(id.contains("chest"))return Material.CHEST;if(id.contains("meteor"))return Material.COMPASS;return Material.SHIELD;}
    private AdminUpdateMenu.Button button(String title,String detail,Material icon,Runnable action,Player p){return new AdminUpdateMenu.Button(title,detail,icon,()->{if(allowed(p))action.run();});}
    private void show(Player p,String title,List<AdminUpdateMenu.Button> b){if(allowed(p))plugin.adminUpdate.show(p,title,b,0);}
    private void back(Player p,List<AdminUpdateMenu.Button> b,Runnable action){b.add(button(t(p,"Zurück","Back"),"",Material.OAK_DOOR,action,p));}
    private void toggle(Player p,List<AdminUpdateMenu.Button> b,String key,String de,String en,Material icon,Runnable back){String path=ROOT+key;boolean value=plugin.getConfig().getBoolean(path);b.add(button(t(p,de,en),state(p,value),icon,()->{plugin.getConfig().set(path,!value);plugin.saveConfig();if(key.equals("enabled")&&value)manager.stopActive();back.run();},p));}
    void home(Player p){if(!allowed(p))return;List<AdminUpdateMenu.Button>b=new ArrayList<>();
        b.add(AdminUpdateMenu.info(t(p,"Client-Schutz","Client protection"),t(p,"Prüfungen auswählen → einschalten → Aktion festlegen. Beliebig viele ausgewählte oder alle aktivierten Checks.","Choose probes → enable → set action. Any number of selected checks or all enabled checks."),Material.SHIELD));
        toggle(p,b,"enabled","Client-Prüfungen","Client probes",Material.LIME_DYE,()->home(p));
        b.add(button(t(p,"Prüfungen & Aktionen","Probes & actions"),manager.joinDefinitions().size()+" / "+manager.definitions().size()+" "+t(p,"beim Beitritt","on join"),Material.SPYGLASS,()->catalog(p),p));
        b.add(button(t(p,"Eigene Client-Prüfung","Custom client probe"),t(p,"Name, Modus, mehrere Schlüssel und Fallback","Name, mode, multiple keys and fallback"),Material.TRIPWIRE_HOOK,()->custom(p),p));
        b.add(button(t(p,"Schnellverwaltung","Quick management"),t(p,"Join und Maßnahme direkt nebeneinander umschalten","Toggle join and action side by side"),Material.COMPARATOR,()->quick(p,0),p));
        b.add(button(t(p,"Optionale Sicherheitsdetektoren","Optional security detectors"),t(p,"Kanal-Fingerprint, Verschleierung und Verhalten","Channel fingerprint, concealment and behavior"),Material.SHIELD,()->plugin.detectors.home(p),p));
        b.add(button(t(p,"Prüfablauf","Verification flow"),t(p,"Join, Abdunklung, Sperre und Zeitlimit","Join, darkening, hold and time limit"),Material.CLOCK,()->flow(p),p));
        b.add(button(t(p,"Discord & Freigaben","Discord & approvals"),t(p,"Alarmkanal, Link und Warteliste","Alert channel, invite and review queue"),Material.BELL,()->discord(p),p));
        b.add(button(t(p,"Erweiterte Einstellungen","Advanced settings"),t(p,"Antwortfristen und bestehende Regeln","Reply deadlines and existing rules"),Material.COMPARATOR,()->advanced(p),p));
        back(p,b,()->manager.menu(p));show(p,t(p,"Client-Schutz","Client protection"),b);
    }
    void catalog(Player p){List<AdminUpdateMenu.Button>b=new ArrayList<>();
        b.add(AdminUpdateMenu.info(t(p,"Prüfungen auswählen","Choose probes"),manager.joinDefinitions().size()+" / "+manager.definitions().size()+" "+t(p,"aktiv beim Beitritt. Anklicken zum Einstellen.","active on join. Select to configure."),Material.SHIELD));
        b.add(button(t(p,"Alle Checks beim Join","All checks on join"),state(p,manager.allOnJoin())+t(p," • Aktiviert alle Checks; bestehende Aktionen gelten"," • Enables all checks; keeps existing actions"),Material.SHIELD,()->{manager.allJoin(!manager.allOnJoin());catalog(p);},p));
        for(var d:manager.definitions()){boolean enabled=manager.enabled(d.id());boolean join=manager.joinIds().contains(d.id());b.add(button(d.name(),state(p,enabled)+" • "+t(p,"Join: ","Join: ")+state(p,join&&enabled)+"\n"+action(p,manager.rules.rule(d.id()).action()),icon(d.id()),()->rule(p,d.id()),p));}
        b.add(button(t(p,"Alle Join-Prüfungen ausschalten","Disable all join probes"),t(p,"Keine automatische Einzelprüfung auswählen","Clear the automatic selection"),Material.GRAY_DYE,()->{manager.clearJoin();catalog(p);},p));
        b.add(button(t(p,"Eigene Client-Prüfung","Custom client probe"),"",Material.TRIPWIRE_HOOK,()->custom(p),p));back(p,b,()->home(p));show(p,t(p,"Prüfungen & Aktionen","Probes & actions"),b);
    }
    void quick(Player p,int requested){
        if(!allowed(p))return;
        var defs=manager.definitions();int pages=Math.max(1,(defs.size()+6)/7),page=Math.max(0,Math.min(pages-1,requested));
        List<AdminUpdateMenu.Button>b=new ArrayList<>();
        b.add(button(t(p,"Alle Join-Prüfungen an/aus","All join probes on/off"),state(p,manager.allOnJoin())+t(p," • Bestehende Aktionen gelten"," • Existing actions apply"),Material.SHIELD,()->{if(manager.allOnJoin()||!manager.joinDefinitions().isEmpty())manager.clearJoin();else manager.allJoin(true);quick(p,page);},p));
        for(var d:defs.subList(page*7,Math.min(defs.size(),(page+1)*7))){
            boolean selected=manager.joinDefinitions().stream().anyMatch(value->value.id().equals(d.id()));
            b.add(button(d.name(),t(p,"Details, Schlüssel und Test","Details, keys and test"),icon(d.id()),()->rule(p,d.id()),p));
            b.add(button(t(p,"Join: ","Join: ")+state(p,selected),d.name(),selected?Material.LIME_DYE:Material.GRAY_DYE,()->{manager.setJoinSelected(d.id(),!selected);quick(p,page);},p));
            String current=manager.rules.rule(d.id()).action();
            b.add(button(action(p,current),d.name()+t(p," • Klick: nächste Maßnahme"," • Click: next action"),current.equals("none")?Material.GRAY_DYE:current.equals("kick")?Material.OAK_DOOR:current.equals("tempban")?Material.IRON_BARS:Material.BELL,()->{String next=switch(current){case "none"->"notify";case "notify"->"kick";case "kick"->"tempban";default->"none";};plugin.getConfig().set(ROOT+"rules."+d.id()+".action",next);plugin.saveConfig();plugin.expansionAudit(p.getName(),null,"Client probe action",d.id()+" -> "+next);quick(p,page);},p));
        }
        if(page>0)b.add(button(t(p,"Vorherige Seite","Previous page"),"",Material.ARROW,()->quick(p,page-1),p));
        if(page+1<pages)b.add(button(t(p,"Nächste Seite","Next page"),"",Material.ARROW,()->quick(p,page+1),p));
        back(p,b,()->home(p));plugin.adminUpdate.showFixed(p,t(p,"Schnellverwaltung","Quick management")+" • "+(page+1)+"/"+pages,b);
    }
    private String action(Player p,String key){return switch(key){case "none"->t(p,"Keine Maßnahme","No action");case "notify"->t(p,"Nur warnen","Notify only");case "kick"->t(p,"Kick","Kick");default->t(p,"Zeitbann","Temporary ban");};}
    void rule(Player p,String id){if(!allowed(p)||!manager.definitionIds().contains(id))return;var rule=manager.rules.rule(id);List<AdminUpdateMenu.Button>b=new ArrayList<>();
        b.add(AdminUpdateMenu.info(manager.definitionName(id),t(p,"Bann/Freigabe nur nach bestätigtem Treffer. Ein Timeout ist kein erkannter Client.","Ban/review only after a confirmed signal. A timeout is not a detected client.")+"\n"+manager.sourceInfo(id),icon(id)));
        b.add(button(t(p,"Prüfung verfügbar","Probe enabled"),state(p,manager.enabled(id)),manager.enabled(id)?Material.LIME_DYE:Material.GRAY_DYE,()->{manager.toggleEnabled(id);rule(p,id);},p));
        b.add(button(t(p,"Beim Beitritt prüfen","Probe on join"),state(p,manager.joinIds().contains(id)&&manager.enabled(id))+" • "+manager.joinIds().size()+" / "+manager.definitions().size(),Material.COMPASS,()->{if(manager.toggleJoin(id)){if(manager.joinIds().contains(id)&&!manager.enabled(id))manager.toggleEnabled(id);}else p.sendMessage(t(p,"§ePrüfung konnte nicht ausgewählt werden.","§eCould not select the probe."));rule(p,id);},p));
        b.add(button(t(p,"Direkt an Spieler testen","Test on a player"),t(p,"Ohne automatische Maßnahmen","Without automatic actions"),Material.SPYGLASS,()->testPlayers(p,id),p));
        b.add(button(t(p,"Aktion bei Treffer","Action on detection"),action(p,rule.action()),Material.SHIELD,()->actions(p,id),p));
        b.add(button(t(p,"Banndauer","Ban duration"),duration(id),Material.CLOCK,()->durations(p,id),p));
        b.add(button(t(p,"Freigabe nach Treffern","Review after detections"),rule.reviewAfter()==0?t(p,"Aus","Off"):Integer.toString(rule.reviewAfter()),Material.TRIPWIRE_HOOK,()->review(p,id),p));
        for(String key:List.of("alert-admins","alert-discord")){boolean value=key.equals("alert-admins")?rule.staffAlert():rule.discordAlert();String path=ROOT+"rules."+id+"."+key;b.add(button(key.equals("alert-admins")?t(p,"Admins warnen","Notify staff"):t(p,"Discord warnen","Notify Discord"),state(p,value),Material.BELL,()->{plugin.getConfig().set(path,!value);plugin.saveConfig();rule(p,id);},p));}
        var definition=manager.definitions().stream().filter(d->d.id().equals(id)).findFirst().orElseThrow();
        b.add(AdminUpdateMenu.info(t(p,"Schlüssel & Prüfmodus","Keys & probe mode"),definition.mode()+" • "+definition.keys().size()+" keys\n"+String.join("\n",definition.keys())+"\nFallback: "+definition.fallback(),Material.TRIPWIRE_HOOK));
        if(id.startsWith("custom-"))b.add(button(t(p,"Eigene Prüfung bearbeiten","Edit custom probe"),t(p,"Name, Modus, Schlüssel und Fallback","Name, mode, keys and fallback"),Material.WRITABLE_BOOK,()->editCustom(p,id),p));
        if(id.startsWith("custom-"))b.add(button(t(p,"Eigene Prüfung entfernen","Remove custom probe"),t(p,"Bestätigung folgt","Requires confirmation"),Material.BARRIER,()->remove(p,id),p));
        back(p,b,()->catalog(p));show(p,manager.definitionName(id),b);
    }
    private String duration(String id){String value=plugin.getConfig().getString(ROOT+"rules."+id+".ban-duration","15m");try{ClientProbeRules.duration(value);return value;}catch(IllegalArgumentException invalid){return "15m";}}
    private void save(Player p,String id,String action,String duration,int review){manager.rules.configure(p.getName(),id,action,duration,review);}
    void testPlayers(Player p,String id){List<AdminUpdateMenu.Button>b=new ArrayList<>();for(Player target:Bukkit.getOnlinePlayers())if(!plugin.isBedrockClient(target)&&p.canSee(target))b.add(button(target.getName(),t(p,"Java • Diagnose ohne Bann/Kick","Java • Diagnostics without ban/kick"),Material.PLAYER_HEAD,()->{manager.testSaved(p,target,id);manager.playerMenu(p,target.getUniqueId());},p));back(p,b,()->rule(p,id));show(p,t(p,"Spieler auswählen","Choose player"),b);}
    void actions(Player p,String id){var rule=manager.rules.rule(id);List<AdminUpdateMenu.Button>b=new ArrayList<>();for(String a:List.of("none","notify","kick","tempban"))b.add(button(action(p,a),rule.action().equals(a)?t(p,"✓ Gewählt","✓ Selected"):"",switch(a){case "none"->Material.GRAY_DYE;case "notify"->Material.BELL;case "kick"->Material.OAK_DOOR;default->Material.REDSTONE_BLOCK;},()->{save(p,id,a,duration(id),rule.reviewAfter());rule(p,id);},p));back(p,b,()->rule(p,id));show(p,t(p,"Aktion auswählen","Choose action"),b);}
    void durations(Player p,String id){List<AdminUpdateMenu.Button>b=new ArrayList<>();for(String value:List.of("5m","15m","30m","1h","1d","7d"))b.add(button(value,duration(id).equals(value)?"✓":"",Material.CLOCK,()->{var r=manager.rules.rule(id);save(p,id,r.action(),value,r.reviewAfter());rule(p,id);},p));b.add(button(t(p,"Eigene Dauer","Custom duration"),t(p,"1s bis 30d, z. B. 2h","1s to 30d, e.g. 2h"),Material.WRITABLE_BOOK,()->plugin.adminUpdate.prompt(p,t(p,"Banndauer","Ban duration"),duration(id),v->{if(allowed(p)){try{ClientProbeRules.duration(v);var r=manager.rules.rule(id);save(p,id,r.action(),v,r.reviewAfter());}catch(IllegalArgumentException e){p.sendMessage(t(p,"§cUngültige Dauer: 1s bis 30d.","§cInvalid duration: 1s to 30d."));}rule(p,id);}}),p));back(p,b,()->rule(p,id));show(p,t(p,"Banndauer","Ban duration"),b);}
    void review(Player p,String id){List<AdminUpdateMenu.Button>b=new ArrayList<>();for(int n:List.of(0,2,3,5,10))b.add(button(n==0?t(p,"Keine Freigabesperre","No review restriction"):n+" "+t(p,"bestätigte Treffer","confirmed detections"),manager.rules.rule(id).reviewAfter()==n?"✓":"",Material.TRIPWIRE_HOOK,()->{var r=manager.rules.rule(id);save(p,id,r.action(),duration(id),n);rule(p,id);},p));b.add(button(t(p,"Eigene Trefferzahl","Custom detection count"),t(p,"0–100; 0 = aus","0–100; 0 = off"),Material.WRITABLE_BOOK,()->plugin.adminUpdate.prompt(p,t(p,"Trefferzahl 0–100","Detection count 0–100"),Integer.toString(manager.rules.rule(id).reviewAfter()),v->{if(allowed(p)){try{int n=Integer.parseInt(v);if(n<0||n>100)throw new IllegalArgumentException();var r=manager.rules.rule(id);save(p,id,r.action(),duration(id),n);}catch(IllegalArgumentException invalid){p.sendMessage(t(p,"§cBitte eine Zahl von 0 bis 100 eingeben.","§cEnter a number from 0 to 100."));}rule(p,id);}}),p));back(p,b,()->rule(p,id));show(p,t(p,"Freigabegrenze","Review threshold"),b);}
    void flow(Player p){List<AdminUpdateMenu.Button>b=new ArrayList<>();toggle(p,b,"auto-on-join","Automatisch beim Join","Automatic on join",Material.COMPASS,()->flow(p));toggle(p,b,"hold-player","Während der Prüfung sperren","Hold during verification",Material.SHIELD,()->flow(p));toggle(p,b,"darken-screen","Bildschirm abdunkeln","Darken screen",Material.ENDER_EYE,()->flow(p));toggle(p,b,"show-progress","Kurzen Prüfhinweis zeigen","Show brief verification notice",Material.BOOK,()->flow(p));
        b.add(button(t(p,"Prüfmodus","Probe mode"),ClientProbeManager.quietMode(plugin.getConfig().getString(ROOT+"mode","quiet"))?t(p,"Unauffällig","Quiet"):t(p,"Klassisch","Legacy"),Material.SPYGLASS,()->{plugin.getConfig().set(ROOT+"mode",ClientProbeManager.quietMode(plugin.getConfig().getString(ROOT+"mode","quiet"))?"legacy":"quiet");plugin.saveConfig();flow(p);},p));
        toggle(p,b,"quiet-fallback","Bei fehlender Antwort klassisch wiederholen","Retry legacy on missing reply",Material.REPEATER,()->flow(p));number(p,b,"max-session-seconds","Mindestzeitbudget (Sekunden)","Minimum time budget (seconds)",List.of(15,30,60,120,300),()->flow(p));back(p,b,()->home(p));show(p,t(p,"Prüfablauf","Verification flow"),b);
    }
    private void number(Player p,List<AdminUpdateMenu.Button>b,String key,String de,String en,List<Integer> values,Runnable returnTo){b.add(button(t(p,de,en),Integer.toString(plugin.getConfig().getInt(ROOT+key)),Material.CLOCK,()->{List<AdminUpdateMenu.Button>choices=new ArrayList<>();for(int n:values)choices.add(button(Integer.toString(n),"",Material.CLOCK,()->{plugin.getConfig().set(ROOT+key,n);plugin.saveConfig();returnTo.run();},p));back(p,choices,returnTo);show(p,t(p,de,en),choices);},p));}
    void advanced(Player p){List<AdminUpdateMenu.Button>b=new ArrayList<>();toggle(p,b,"console-summary","Nur abschließende Konsolenergebnisse","Final console results only",Material.WRITABLE_BOOK,()->advanced(p));toggle(p,b,"admin-result-summary","Farbige Ergebnisübersicht für Admins","Colored staff result summary",Material.BELL,()->advanced(p));toggle(p,b,"confirm-positive","Treffer erneut prüfen","Confirm positive replies",Material.SHIELD,()->advanced(p));toggle(p,b,"enforce-blocklist","Bestehende alte Sperrliste anwenden","Enforce existing legacy blocklist",Material.BARRIER,()->advanced(p));toggle(p,b,"review-inconclusive","Team-Prüfung bei unklaren Antworten","Review inconclusive replies",Material.TRIPWIRE_HOOK,()->advanced(p));number(p,b,"quiet-timeout-seconds","Antwortfrist (Sekunden)","Reply timeout (seconds)",List.of(2,3,5,10),()->advanced(p));number(p,b,"inconclusive-review-after","Unklare Versuche bis Freigabe","Inconclusive attempts before review",List.of(2,3,5,10),()->advanced(p));number(p,b,"strike-window-days","Trefferfenster (Tage)","Strike window (days)",List.of(1,3,7,14,30),()->advanced(p));back(p,b,()->home(p));show(p,t(p,"Erweiterte Einstellungen","Advanced settings"),b);}
    private void channelReply(Player p,String value){String result=manager.channel(p.getName(),value);String english=switch(result){
        case "Discord-Bot nicht initialisiert."->"Discord bot not initialized.";
        case "Discord-Bot ist nicht bereit.","Discord-Bot ist noch nicht bereit."->"Discord bot is not ready.";
        case "Es ist bereits ein Kanal konfiguriert."->"An alert channel is already configured.";
        case "Eine Kanalerstellung läuft bereits."->"Channel creation is already in progress.";
        case "Client-Kanal deaktiviert."->"Client alert channel disabled.";
        case "Client-Kanal wird geprüft und gespeichert."->"Client channel is being validated and saved.";
        case "Discord-Warteschlange ist voll."->"Discord queue is full.";
        case "Kanal-ID, create oder off."->"Enter a Discord channel ID.";
        default->"A private alert channel is being created and saved. The bot needs Manage Channels permission.";
    };p.sendMessage(t(p,result,english));}
    void discord(Player p){List<AdminUpdateMenu.Button>b=new ArrayList<>();toggle(p,b,"discord-alerts","Discord-Alarme","Discord alerts",Material.BELL,()->discord(p));toggle(p,b,"review-discord-only","Freigabe nur in Discord","Approval through Discord only",Material.TRIPWIRE_HOOK,()->discord(p));
        b.add(button(t(p,"Privaten Alarmkanal erstellen","Create private alert channel"),t(p,"Ein Klick; vorhandener Bot benötigt Kanalrechte","One click; bot needs channel permissions"),Material.BELL,()->{channelReply(p,"create");discord(p);},p));
        b.add(button(t(p,"Bestehenden Kanal verwenden","Use existing channel"),t(p,"Discord-Kanal-ID eingeben","Enter Discord channel ID"),Material.WRITABLE_BOOK,()->plugin.adminUpdate.prompt(p,t(p,"Discord-Kanal-ID","Discord channel ID"),plugin.getConfig().getString("discord-bot.moderation-log.client-probes-channel-id",""),v->{if(allowed(p)){channelReply(p,v);discord(p);}}),p));
        b.add(button(t(p,"Alarmkanal abschalten","Disable alert channel"),"",Material.GRAY_DYE,()->{channelReply(p,"off");discord(p);},p));
        b.add(button(t(p,"Discord-Link ändern","Change Discord invite"),t(p,"Gilt auch auf Kick-/Bannbildschirmen","Also shown on kick/ban screens"),Material.WRITABLE_BOOK,()->plugin.adminUpdate.prompt(p,t(p,"Discord-Link oder Code","Discord invite or code"),plugin.discordInvite.code(),v->{if(allowed(p)){plugin.discordInvite.set(p,new String[]{v});discord(p);}}),p));
        b.add(button(t(p,"Freigabe-Warteliste","Review queue"),Integer.toString(manager.access.reviewQueue().size()),Material.PLAYER_HEAD,()->manager.reviewMenu(p),p));back(p,b,()->home(p));show(p,t(p,"Discord & Freigaben","Discord & approvals"),b);
    }
    private record Draft(String id,String name,String mode,String fallback,List<String> keys){Draft{keys=List.copyOf(keys);}}
    void custom(Player p){List<AdminUpdateMenu.Button>b=new ArrayList<>();b.add(AdminUpdateMenu.info(t(p,"Eigene Client-Prüfungen","Custom client probes"),t(p,"TRANSLATE, KEYBIND oder METEOR; mehrere Varianten werden zu einem Ergebnis zusammengefasst. Neue Prüfungen führen zunächst keine Maßnahmen aus.","TRANSLATE, KEYBIND or METEOR; multiple variants form one result. New probes initially apply no actions."),Material.TRIPWIRE_HOOK));b.add(button(t(p,"Neue Prüfung erstellen","Create custom probe"),t(p,"Name, Schlüssel, Modus und Fallback","Name, keys, mode and fallback"),Material.WRITABLE_BOOK,()->editCustom(p,null),p));for(var d:manager.definitions())if(d.id().startsWith("custom-"))b.add(button(d.name(),state(p,manager.enabled(d.id())),icon(d.id()),()->rule(p,d.id()),p));back(p,b,()->home(p));show(p,t(p,"Eigene Clients","Custom clients"),b);}
    void editCustom(Player p,String id){var existing=id==null?null:manager.definitions().stream().filter(d->d.id().equals(id)).findFirst().orElse(null);draft(p,existing==null?new Draft(null,"","TRANSLATE","sas:custom",List.of()):new Draft(id,existing.name(),existing.mode(),existing.fallback(),existing.keys()));}
    private void draft(Player p,Draft d){if(!allowed(p))return;List<AdminUpdateMenu.Button>b=new ArrayList<>();b.add(AdminUpdateMenu.info(t(p,"Client-Prüfung konfigurieren","Configure client probe"),t(p,"Erst Speichern übernimmt die Änderungen.","Changes apply only after saving."),Material.SHIELD));
        b.add(button(t(p,"Anzeigename","Display name"),d.name(),Material.NAME_TAG,()->plugin.adminUpdate.prompt(p,t(p,"Name (1–48 Zeichen)","Name (1–48 characters)"),d.name(),value->{if(allowed(p))try{draft(p,new Draft(d.id(),ClientProbeManager.validName(value),d.mode(),d.fallback(),d.keys()));}catch(IllegalArgumentException error){p.sendMessage(t(p,"§cUngültiger Name.","§cInvalid name."));draft(p,d);}}),p));
        b.add(button(t(p,"Schlüssel / Varianten","Keys / variants"),d.keys().size()+" • "+String.join(", ",d.keys()),Material.TRIPWIRE_HOOK,()->plugin.adminUpdate.prompt(p,t(p,"Schlüssel mit Komma trennen","Separate keys with commas"),String.join(", ",d.keys()),value->{if(allowed(p))try{List<String> keys=Arrays.stream(value.split("[,\\n|]+")).map(String::strip).filter(v->!v.isEmpty()).map(ClientProbeManager::validKey).distinct().toList();if(keys.isEmpty())throw new IllegalArgumentException();draft(p,new Draft(d.id(),d.name(),d.mode(),d.fallback(),keys));}catch(IllegalArgumentException error){p.sendMessage(t(p,"§cUngültige Schlüssel.","§cInvalid keys."));draft(p,d);}}),p));
        b.add(button(t(p,"Prüfmodus","Probe mode"),d.mode(),Material.COMPARATOR,()->{List<AdminUpdateMenu.Button>choices=new ArrayList<>();for(String mode:List.of("TRANSLATE","KEYBIND","METEOR"))choices.add(button(mode,d.mode().equals(mode)?"✓":"",Material.SHIELD,()->draft(p,new Draft(d.id(),d.name(),mode,d.fallback(),d.keys())),p));back(p,choices,()->draft(p,d));show(p,t(p,"Prüfmodus auswählen","Choose probe mode"),choices);},p));
        b.add(button(t(p,"Fallback ohne Mod","Fallback without mod"),d.fallback(),Material.PAPER,()->plugin.adminUpdate.prompt(p,t(p,"Fallback, z. B. sas:custom","Fallback, e.g. sas:custom"),d.fallback(),value->{if(allowed(p))try{draft(p,new Draft(d.id(),d.name(),d.mode(),ClientProbeManager.validKey(value),d.keys()));}catch(IllegalArgumentException error){p.sendMessage(t(p,"§cUngültiger Fallback.","§cInvalid fallback."));draft(p,d);}}),p));
        b.add(button(t(p,"Speichern","Save"),t(p,"Danach Join-Auswahl und Aktion festlegen","Choose join selection and action afterwards"),Material.LIME_DYE,()->{try{rule(p,manager.saveCustom(p.getName(),d.id(),d.name(),d.mode(),d.fallback(),d.keys()));}catch(IOException|IllegalArgumentException error){p.sendMessage(t(p,"§cNicht gespeichert. Name, Schlüssel, Modus und eindeutigen Fallback prüfen.","§cNot saved. Check name, keys, mode and distinct fallback."));draft(p,d);}},p));back(p,b,()->custom(p));show(p,t(p,"Eigene Client-Prüfung","Custom client probe"),b);
    }
    void remove(Player p,String id){List<AdminUpdateMenu.Button>b=new ArrayList<>();b.add(button(t(p,"Eigene Prüfung jetzt entfernen","Remove custom probe now"),manager.definitionName(id),Material.BARRIER,()->{try{manager.deleteCustom(p.getName(),id);}catch(IOException e){p.sendMessage(t(p,"§cKonnte nicht gespeichert werden.","§cCould not save changes."));}custom(p);},p));back(p,b,()->rule(p,id));show(p,t(p,"Entfernen bestätigen","Confirm removal"),b);}
}
